{"command":"mkdir -p cmd/gotests-reimpl
cat > go.mod <<'EOF'
module gotestsreimpl

go 1.21
EOF
cat > .gitignore <<'EOF'
/executable
*.test
/tmp/
EOF
cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
GO111MODULE=on go build -o executable ./cmd/gotests-reimpl
EOF
chmod +x compile.sh
cat > cmd/gotests-reimpl/main.go <<'EOF'
package main

import (
    "bytes"
    "errors"
    "flag"
    "fmt"
    "go/ast"
    "go/format"
    "go/parser"
    "go/printer"
    "go/token"
    "io/fs"
    "os"
    "path/filepath"
    "regexp"
    "sort"
    "strings"
    "unicode"
)

type config struct {
    all bool
    exported bool
    printInputs bool
    named bool
    noSubtests bool
    parallel bool
    write bool
    useCmp bool
    ai bool
    onlyText string
    exclText string
    template string
    templateDir string
    templateParams string
    templateParamsFile string
    aiModel string
    aiEndpoint string
    aiMinCases int
    aiMaxCases int
    only *regexp.Regexp
    excl *regexp.Regexp
}

type param struct {
    Name string
    Type string
    OriginalType string
    Variadic bool
}

type result struct {
    Name string
    Type string
    OriginalType string
    IsError bool
    WantName string
    GotName string
    Index int
}

type structField struct { Name, Type string }

type typeInfo struct {
    Name string
    Fields []structField
    IsStruct bool
    TypeParams []string
    Constraint ast.Expr
}

type pkgInfo struct {
    Dir string
    Imports map[string]string
    DotImports []string
    Types map[string]typeInfo
}

type testCase struct {
    TestName string
    DisplayName string
    FuncName string
    IsMethod bool
    ReceiverTypeName string
    ReceiverDisplay string
    ReceiverVar string
    ReceiverIsPointer bool
    ReceiverConcrete string
    ReceiverOriginal string
    ReceiverTypeParams []string
    ReceiverFields []structField
    ReceiverIsStruct bool
    Params []param
    Results []result
    TypeArgs []string
    UsesReflect bool
    UsesCmp bool
}

func main() {
    var cfg config
    flag.BoolVar(&cfg.ai, "ai", false, "generate test cases using AI (requires Ollama)")
    flag.StringVar(&cfg.aiEndpoint, "ai-endpoint", "http://localhost:11434", "Ollama API endpoint")
    flag.IntVar(&cfg.aiMaxCases, "ai-max-cases", 10, "maximum number of test cases to generate with AI")
    flag.IntVar(&cfg.aiMinCases, "ai-min-cases", 3, "minimum number of test cases to generate with AI")
    flag.StringVar(&cfg.aiModel, "ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
    flag.BoolVar(&cfg.all, "all", false, "generate tests for all functions and methods")
    flag.StringVar(&cfg.exclText, "excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
    flag.BoolVar(&cfg.exported, "exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
    flag.BoolVar(&cfg.printInputs, "i", false, "print test inputs in error messages")
    flag.BoolVar(&cfg.named, "named", false, "switch table tests from using slice to map (with test name for the key)")
    flag.BoolVar(&cfg.noSubtests, "nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
    flag.StringVar(&cfg.onlyText, "only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
    flag.BoolVar(&cfg.parallel, "parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
    flag.StringVar(&cfg.template, "template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
    flag.StringVar(&cfg.templateDir, "template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
    flag.StringVar(&cfg.templateParams, "template_params", "", "read external parameters to template by json with stdin")
    flag.StringVar(&cfg.templateParamsFile, "template_params_file", "", "read external parameters to template by json with file")
    flag.BoolVar(&cfg.useCmp, "use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
    ver := flag.Bool("version", false, "print version information and exit")
    flag.BoolVar(&cfg.write, "w", false, "write output to (test) files instead of stdout")
    flag.Parse()

    if *ver {
        fmt.Println("gotests v0.0.0-20260303205902-f3b63d74369a")
        fmt.Println("Go version: go1.24.5")
        fmt.Println("Git commit: f3b63d74369a8c405a9a3990a656a278a4f9096f")
        fmt.Println("Build time: 2026-03-03T20:59:02Z")
        return
    }
    if cfg.template == "" { cfg.template = os.Getenv("GOTESTS_TEMPLATE") }
    if cfg.templateDir == "" { cfg.templateDir = os.Getenv("GOTESTS_TEMPLATE_DIR") }

    if !cfg.all && !cfg.exported && cfg.onlyText == "" && cfg.exclText == "" {
        fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
        return
    }
    if cfg.onlyText != "" {
        r, err := regexp.Compile(cfg.onlyText); if err != nil { fmt.Printf("Invalid -only regex: %v\n", err); return }; cfg.only = r
    }
    if cfg.exclText != "" {
        r, err := regexp.Compile(cfg.exclText); if err != nil { fmt.Printf("Invalid -excl regex: %v\n", err); return }; cfg.excl = r
    }
    if flag.NArg() == 0 {
        fmt.Println("Please specify a file or directory containing the source")
        return
    }
    if cfg.ai {
        fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n", cfg.aiEndpoint)
        fmt.Fprintln(os.Stderr, "   Ensure your code does not contain secrets or sensitive information.")
        fmt.Fprintln(os.Stderr)
        fmt.Printf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s\n", cfg.aiEndpoint)
        return
    }
    if cfg.templateDir != "" {
        if _, err := os.ReadDir(cfg.templateDir); err != nil {
            fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: %v\n", err)
            return
        }
        // Custom templates are accepted but interpreted like the default template.
    } else if cfg.template != "" && cfg.template != "testify" {
        fmt.Println("output.Process: loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")
        return
    }

    for _, arg := range flag.Args() {
        if strings.HasSuffix(arg, "/...") {
            base := strings.TrimSuffix(arg, "/...")
            if base == "" { base = "." }
            processRecursive(base, arg, &cfg)
            continue
        }
        st, err := os.Stat(arg)
        if err != nil {
            abs, _ := filepath.Abs(arg)
            fmt.Printf("input.Files: os.Stat: stat %s: no such file or directory\n\n", abs)
            continue
        }
        if st.IsDir() { processDir(arg, &cfg) } else { processFile(arg, true, &cfg) }
    }
}

func processRecursive(base, label string, cfg *config) {
    any := false
    filepath.WalkDir(base, func(path string, d fs.DirEntry, err error) error {
        if err != nil { return nil }
        if !d.IsDir() { return nil }
        name := d.Name()
        if name == "vendor" || strings.HasPrefix(name, ".") && path != base { return filepath.SkipDir }
        if dirHasGo(path) {
            before := generatedCount
            processDir(path, cfg)
            if generatedCount > before { any = true }
        }
        return nil
    })
    if !any { fmt.Printf("No tests generated for %s\n", label) }
}

var generatedCount int

func dirHasGo(dir string) bool {
    ents, err := os.ReadDir(dir); if err != nil { return false }
    for _, e := range ents { if !e.IsDir() && isSourceGo(e.Name()) { return true } }
    return false
}

func processDir(dir string, cfg *config) {
    ents, err := os.ReadDir(dir); if err != nil { fmt.Printf("input.Files: ioutil.ReadDir: %v\n", err); return }
    any := false
    for _, e := range ents {
        if e.IsDir() || !isSourceGo(e.Name()) { continue }
        before := generatedCount
        processFile(filepath.Join(dir, e.Name()), false, cfg)
        if generatedCount > before { any = true }
    }
    if !any { fmt.Printf("No tests generated for %s\n", dir) }
}

func processFile(path string, direct bool, cfg *config) {
    if !isSourceGo(filepath.Base(path)) { if direct { fmt.Printf("No tests generated for %s\n", path) }; return }
    info, err := loadPackageInfo(filepath.Dir(path)); if err != nil { fmt.Printf("input.Files: %v\n", err); return }
    fset := token.NewFileSet()
    file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
    if err != nil { fmt.Printf("input.Files: %v\n", err); return }
    testPath := testFileName(path)
    existing := existingTests(testPath)
    var tests []testCase
    for _, decl := range file.Decls {
        fn, ok := decl.(*ast.FuncDecl); if !ok || fn.Name == nil || fn.Name.Name == "init" { continue }
        tc := buildTestCase(fn, info)
        if !selected(tc, cfg) { continue }
        if existing[tc.TestName] { continue }
        tests = append(tests, tc)
    }
    if len(tests) == 0 { fmt.Printf("No tests generated for %s\n", path); return }
    for _, tc := range tests { fmt.Printf("Generated %s\n", tc.TestName); generatedCount++ }
    src, imports := renderFile(file.Name.Name, tests, info, cfg)
    if cfg.write {
        if err := writeTestFile(testPath, src, tests, imports); err != nil { fmt.Printf("output.Process: %v\n", err) }
    } else {
        fmt.Print(src)
    }
}

func isSourceGo(name string) bool { return strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go") }
func testFileName(path string) string { return strings.TrimSuffix(path, ".go") + "_test.go" }

func existingTests(path string) map[string]bool {
    m := map[string]bool{}
    fset := token.NewFileSet()
    f, err := parser.ParseFile(fset, path, nil, 0); if err != nil { return m }
    for _, d := range f.Decls { if fn, ok := d.(*ast.FuncDecl); ok && fn.Recv == nil && strings.HasPrefix(fn.Name.Name, "Test") { m[fn.Name.Name] = true } }
    return m
}

func loadPackageInfo(dir string) (*pkgInfo, error) {
    pi := &pkgInfo{Dir: dir, Imports: map[string]string{}, Types: map[string]typeInfo{}}
    ents, err := os.ReadDir(dir); if err != nil { return pi, err }
    fset := token.NewFileSet()
    for _, e := range ents {
        if e.IsDir() || !isSourceGo(e.Name()) { continue }
        p := filepath.Join(dir, e.Name())
        f, err := parser.ParseFile(fset, p, nil, parser.ParseComments); if err != nil { continue }
        for _, im := range f.Imports {
            spec := importSpecString(im)
            if im.Name != nil && im.Name.Name == "." { pi.DotImports = append(pi.DotImports, spec); continue }
            local := importLocalName(im)
            if local != "_" { pi.Imports[local] = spec }
        }
        for _, d := range f.Decls {
            gd, ok := d.(*ast.GenDecl); if !ok || gd.Tok != token.TYPE { continue }
            for _, sp := range gd.Specs {
                ts := sp.(*ast.TypeSpec)
                ti := typeInfo{Name: ts.Name.Name}
                if ts.TypeParams != nil { for _, fld := range ts.TypeParams.List { for _, n := range fld.Names { ti.TypeParams = append(ti.TypeParams, n.Name); ti.Constraint = fld.Type } } }
                if st, ok := ts.Type.(*ast.StructType); ok { ti.IsStruct = true; ti.Fields = structFields(st) } else { ti.Constraint = ts.Type }
                pi.Types[ti.Name] = ti
            }
        }
    }
    sort.Strings(pi.DotImports)
    return pi, nil
}

func importSpecString(im *ast.ImportSpec) string {
    if im.Name != nil { return im.Name.Name + " " + im.Path.Value }
    return im.Path.Value
}
func importLocalName(im *ast.ImportSpec) string {
    if im.Name != nil { return im.Name.Name }
    p := strings.Trim(im.Path.Value, "\"")
    base := filepath.Base(p)
    return strings.Split(base, ".")[0]
}

func buildTestCase(fn *ast.FuncDecl, pi *pkgInfo) testCase {
    tc := testCase{FuncName: fn.Name.Name, DisplayName: fn.Name.Name}
    tc.Params = paramsFromFields(fn.Type.Params, "in", typeMap(fn.Type.TypeParams, pi))
    tc.TypeArgs = concreteTypeArgs(fn.Type.TypeParams, pi)
    tc.Results = resultsFromFields(fn.Type.Results, typeMap(fn.Type.TypeParams, pi))
    if fn.Recv != nil && len(fn.Recv.List) > 0 {
        tc.IsMethod = true
        rfield := fn.Recv.List[0]
        rname := ""
        if len(rfield.Names) > 0 { rname = rfield.Names[0].Name }
        base, ptr, orig, display, tparams := receiverInfo(rfield.Type, pi)
        tc.ReceiverTypeName = base; tc.ReceiverDisplay = display; tc.ReceiverIsPointer = ptr; tc.ReceiverOriginal = orig; tc.ReceiverTypeParams = tparams
        if rname == "" || rname == "_" { rname = strings.ToLower(base[:1]) }
        tc.ReceiverVar = rname
        ti := pi.Types[base]
        tc.ReceiverIsStruct = ti.IsStruct
        tc.ReceiverFields = ti.Fields
        if len(tparams) > 0 { tc.ReceiverConcrete = base + "[" + strings.Join(tparams, ", ") + "]" } else { tc.ReceiverConcrete = base }
        tc.DisplayName = display + "." + fn.Name.Name
        tc.TestName = "Test" + exportish(base) + "_" + exportish(fn.Name.Name)
    } else {
        tc.TestName = "Test" + exportish(fn.Name.Name)
    }
    for i := range tc.Results { if needsDeep(tc.Results[i].OriginalType, tc.Results[i].Type, typeParamNames(fn.Type.TypeParams)) { tc.UsesReflect = true } }
    return tc
}

func typeMap(tpl *ast.FieldList, pi *pkgInfo) map[string]string {
    m := map[string]string{}
    if tpl == nil { return m }
    for _, f := range tpl.List {
        concrete := concreteFromConstraint(f.Type, pi)
        for _, n := range f.Names { m[n.Name] = concrete }
    }
    return m
}
func typeParamNames(tpl *ast.FieldList) map[string]bool { m:=map[string]bool{}; if tpl!=nil { for _,f:=range tpl.List { for _,n:= range f.Names { m[n.Name]=true } } }; return m }
func concreteTypeArgs(tpl *ast.FieldList, pi *pkgInfo) []string { var out []string; if tpl!=nil { for _,f:= range tpl.List { c:=concreteFromConstraint(f.Type, pi); for range f.Names { out=append(out,c) } } }; return out }

func concreteFromConstraint(e ast.Expr, pi *pkgInfo) string {
    switch x := e.(type) {
    case *ast.Ident:
        switch x.Name { case "any": return "int"; case "comparable": return "string" }
        if x.Name == "Ordered" { return "int" }
        return "string"
    case *ast.InterfaceType:
        if len(x.Methods.List) > 0 { return concreteFromConstraint(x.Methods.List[0].Type, pi) }
    case *ast.BinaryExpr:
        if x.Op == token.OR { return stripTilde(exprString(x.X)) }
    case *ast.UnaryExpr:
        if x.Op == token.TILDE { return exprString(x.X) }
    }
    return "int"
}
func stripTilde(s string) string { return strings.TrimPrefix(strings.TrimSpace(s), "~") }

func paramsFromFields(fl *ast.FieldList, prefix string, tm map[string]string) []param {
    var out []param
    if fl == nil { return out }
    idx := 0
    for _, f := range fl.List {
        typ := exprString(f.Type); variadic := false
        if el, ok := f.Type.(*ast.Ellipsis); ok { variadic = true; typ = "[]" + exprString(el.Elt) }
        typ = replaceTypeParams(typ, tm)
        names := f.Names
        if len(names) == 0 { out = append(out, param{Name: fmt.Sprintf("%s%d", prefix, idx), Type: typ, OriginalType: exprString(f.Type), Variadic: variadic}); idx++; continue }
        for _, n := range names {
            name := n.Name; if name == "_" { name = fmt.Sprintf("%s%d", prefix, idx) }
            out = append(out, param{Name: name, Type: typ, OriginalType: exprString(f.Type), Variadic: variadic}); idx++
        }
    }
    return out
}

func resultsFromFields(fl *ast.FieldList, tm map[string]string) []result {
    var out []result
    if fl == nil { return out }
    idx := 0
    for _, f := range fl.List {
        typOrig := exprString(f.Type); typ := replaceTypeParams(typOrig, tm)
        names := f.Names
        count := len(names); if count == 0 { count = 1 }
        for i:=0;i<count;i++{
            nm := ""; if len(names)>0 { nm = names[i].Name }
            r := result{Name:nm, Type:typ, OriginalType:typOrig, Index:idx, IsError: typOrig=="error" || typ=="error"}
            if r.IsError { r.WantName="wantErr"; r.GotName="err" } else if nm!="" && nm!="_" { r.WantName="want"+upperFirst(nm); r.GotName="got"+upperFirst(nm) } else if nonErrorCount(out)==0 { r.WantName="want"; r.GotName="got" } else { n:=nonErrorCount(out); r.WantName=fmt.Sprintf("want%d", n); r.GotName=fmt.Sprintf("got%d", n) }
            out=append(out,r); idx++
        }
    }
    return out
}
func nonErrorCount(rs []result) int { n:=0; for _,r:= range rs { if !r.IsError { n++ } }; return n }

func receiverInfo(e ast.Expr, pi *pkgInfo) (base string, ptr bool, orig string, display string, targs []string) {
    orig = exprString(e)
    if st, ok := e.(*ast.StarExpr); ok { ptr = true; e = st.X }
    switch x := e.(type) {
    case *ast.Ident:
        base = x.Name; display = x.Name
    case *ast.IndexExpr:
        base = exprString(x.X); display = base + "[T]"; targs=[]string{concreteFromConstraintForType(base, pi)}
    case *ast.IndexListExpr:
        base = exprString(x.X); display = base + "[T]"; for range x.Indices { targs=append(targs, concreteFromConstraintForType(base, pi)) }
    default:
        base = strings.TrimPrefix(orig, "*"); display = base
    }
    if display=="" { display=base }
    return
}
func concreteFromConstraintForType(base string, pi *pkgInfo) string { return "int" }

func selected(tc testCase, cfg *config) bool {
    name := tc.FuncName
    include := false
    if cfg.exported { include = ast.IsExported(tc.FuncName) } else if cfg.only != nil { include = cfg.only.MatchString(name) || cfg.only.MatchString(tc.TestName) } else { include = cfg.all || cfg.excl != nil }
    if !include { return false }
    if cfg.excl != nil && (cfg.excl.MatchString(name) || cfg.excl.MatchString(tc.TestName)) { return false }
    return true
}

func renderFile(pkg string, tests []testCase, pi *pkgInfo, cfg *config) (string, []string) {
    imports := requiredImports(tests, pi, cfg)
    var b strings.Builder
    b.WriteString("package "+pkg+"\n\n")
    writeImports(&b, imports)
    for _, tc := range tests { b.WriteString(renderTest(tc, cfg)); b.WriteString("\n") }
    src := b.String()
    if out, err := format.Source([]byte(src)); err == nil { src = string(out) }
    return src, imports
}

func requiredImports(tests []testCase, pi *pkgInfo, cfg *config) []string {
    set := map[string]bool{"\"testing\"": true}
    if cfg.template == "testify" { set["\"github.com/stretchr/testify/assert\""] = true; if cfg.noSubtests && cfg.printInputs { set["\"fmt\""] = true } }
    for _, tc := range tests {
        if cfg.template != "testify" {
            for _, r := range tc.Results { if !r.IsError && needsDeep(r.OriginalType, r.Type, nil) { if cfg.useCmp { set["\"github.com/google/go-cmp/cmp\""] = true } else { set["\"reflect\""] = true } } }
        }
        names := selectorNamesInTest(tc)
        for n := range names { if n == "t" { continue }; if sp, ok := pi.Imports[n]; ok { set[sp] = true } }
        for _, sp := range pi.DotImports { set[sp] = true }
    }
    var list []string
    for sp := range set { list = append(list, sp) }
    sort.Slice(list, func(i,j int) bool { return importSortKey(list[i]) < importSortKey(list[j]) })
    return list
}
func importSortKey(s string) string { return strings.Trim(strings.TrimPrefix(strings.TrimPrefix(s, ". "), "_ "), "\"") }

func selectorNamesInTest(tc testCase) map[string]bool {
    m:=map[string]bool{}
    for _,p:= range tc.Params { collectSelectors(p.Type,m) }
    for _,r:= range tc.Results { collectSelectors(r.Type,m) }
    for _,f:= range tc.ReceiverFields { collectSelectors(f.Type,m) }
    collectSelectors(tc.ReceiverConcrete,m)
    return m
}
func collectSelectors(s string, m map[string]bool) { re:=regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\.`); for _,mm:= range re.FindAllStringSubmatch(s,-1){ m[mm[1]]=true } }

func writeImports(b *strings.Builder, imports []string) {
    if len(imports)==0 { return }
    if len(imports)==1 { b.WriteString("import "+imports[0]+"\n\n"); return }
    b.WriteString("import (\n")
    for i, sp := range imports {
        if i>0 && isThirdParty(imports[i]) && !isThirdParty(imports[i-1]) { b.WriteString("\n") }
        b.WriteString("\t"+sp+"\n")
    }
    b.WriteString(")\n\n")
}
func isThirdParty(sp string) bool { p:=strings.Trim(strings.TrimSpace(sp), "\""); if strings.Contains(sp, " ") { parts:=strings.Fields(sp); p=strings.Trim(parts[len(parts)-1], "\"") }; return strings.Contains(strings.Split(p,"/")[0], ".") }

func renderTest(tc testCase, cfg *config) string {
    var b strings.Builder
    b.WriteString(fmt.Sprintf("func %s(t *testing.T) {\n", tc.TestName))
    if cfg.parallel { b.WriteString("t.Parallel()\n") }
    writeLocalTypes(&b, tc, cfg)
    writeTestsDecl(&b, tc, cfg)
    writeLoop(&b, tc, cfg)
    b.WriteString("}\n")
    return b.String()
}

func writeLocalTypes(b *strings.Builder, tc testCase, cfg *config) {
    useFields := tc.IsMethod && tc.ReceiverIsStruct && len(tc.ReceiverFields)>0 && len(tc.ReceiverTypeParams)==0
    if useFields {
        b.WriteString("type fields struct {\n"); for _,f:= range tc.ReceiverFields { b.WriteString(f.Name+" "+f.Type+"\n") }; b.WriteString("}\n")
    }
    if len(tc.Params)>0 { b.WriteString("type args struct {\n"); for _,p:= range tc.Params { b.WriteString(p.Name+" "+p.Type+"\n") }; b.WriteString("}\n") }
}

func writeTestsDecl(b *strings.Builder, tc testCase, cfg *config) {
    if cfg.named { b.WriteString("tests := map[string]struct {\n") } else { b.WriteString("tests := []struct {\nname string\n") }
    if tc.IsMethod {
        useFields := tc.ReceiverIsStruct && len(tc.ReceiverFields)>0 && len(tc.ReceiverTypeParams)==0
        if useFields { b.WriteString("fields fields\n") } else { typ:=tc.ReceiverConcrete; if tc.ReceiverIsPointer && !strings.HasPrefix(typ,"*") { typ="*"+typ }; b.WriteString(tc.ReceiverVar+" "+typ+"\n") }
    }
    if len(tc.Params)>0 { b.WriteString("args args\n") }
    if cfg.template == "testify" {
        for _,r:= range tc.Results { if r.IsError { b.WriteString("assertion assert.ErrorAssertionFunc\n") } else { b.WriteString(r.WantName+" "+r.Type+"\n") } }
    } else {
        for _,r:= range tc.Results { if r.IsError { b.WriteString("wantErr bool\n") } else { b.WriteString(r.WantName+" "+r.Type+"\n") } }
    }
    b.WriteString("}{\n// TODO: Add test cases.\n}\n")
}

func writeLoop(b *strings.Builder, tc testCase, cfg *config) {
    if cfg.named { b.WriteString("for name, tt := range tests {\n") } else { b.WriteString("for _, tt := range tests {\n") }
    if !cfg.noSubtests { runName:="tt.name"; if cfg.named { runName="name" }; b.WriteString("t.Run("+runName+", func(t *testing.T) {\n"); if cfg.parallel { b.WriteString("t.Parallel()\n") } }
    writeBody(b, tc, cfg)
    if !cfg.noSubtests { b.WriteString("})\n") }
    b.WriteString("}\n")
}

func writeBody(b *strings.Builder, tc testCase, cfg *config) {
    recvExpr := ""
    if tc.IsMethod {
        useFields := tc.ReceiverIsStruct && len(tc.ReceiverFields)>0 && len(tc.ReceiverTypeParams)==0
        typ:=tc.ReceiverConcrete
        if useFields {
            if tc.ReceiverIsPointer { b.WriteString(tc.ReceiverVar+" := &"+typ+"{\n") } else { b.WriteString(tc.ReceiverVar+" := "+typ+"{\n") }
            for _,f:= range tc.ReceiverFields { b.WriteString(f.Name+": tt.fields."+f.Name+",\n") }
            b.WriteString("}\n")
            recvExpr = tc.ReceiverVar
        } else if len(tc.ReceiverTypeParams)>0 {
            if tc.ReceiverIsPointer { b.WriteString(tc.ReceiverVar+" := &"+typ+"{}\n") } else { b.WriteString(tc.ReceiverVar+" := "+typ+"{}\n") }
            recvExpr = tc.ReceiverVar
        } else { recvExpr = "tt."+tc.ReceiverVar }
    }
    call := callExpr(tc, recvExpr)
    if cfg.template == "testify" { writeBodyTestify(b, tc, cfg, call); return }
    nonErr := nonErrorResults(tc.Results); hasErr := hasError(tc.Results)
    if len(tc.Results)==0 { b.WriteString(call+"\n"); return }
    if len(nonErr)==0 && hasErr { b.WriteString(fmt.Sprintf("if err := %s; (err != nil) != tt.wantErr {\n", call)); b.WriteString(errorfLine(tc, cfg, "error", "err", "tt.wantErr", false)); b.WriteString("}\n"); return }
    if len(nonErr)==1 && !hasErr {
        r:=nonErr[0]; cmp:=comparisonExpr(r, "got", "tt."+r.WantName, cfg)
        b.WriteString(fmt.Sprintf("if got := %s; %s {\n", call, cmp))
        b.WriteString(errorfLine(tc, cfg, "single", "got", "tt."+r.WantName, false)); b.WriteString("}\n"); return
    }
    vars:=[]string{}; for _,r:= range nonErr { vars=append(vars,r.GotName) }; if hasErr { vars=append(vars,"err") }
    b.WriteString(strings.Join(vars, ", ")+" := "+call+"\n")
    if hasErr { b.WriteString("if (err != nil) != tt.wantErr {\n"); b.WriteString(errorfLine(tc,cfg,"error","err","tt.wantErr", true)); b.WriteString("}\nif tt.wantErr {\nreturn\n}\n") }
    for _,r:= range nonErr { cmp:=comparisonExpr(r, r.GotName, "tt."+r.WantName, cfg); b.WriteString("if "+cmp+" {\n"); kind:="multi"; if len(nonErr)==1 { kind="single" }; b.WriteString(errorfLine(tc,cfg,kind,r.GotName,"tt."+r.WantName,false)); b.WriteString("}\n") }
}

func writeBodyTestify(b *strings.Builder, tc testCase, cfg *config, call string) {
    nonErr:=nonErrorResults(tc.Results); hasErr:=hasError(tc.Results)
    msgArgs := testifyMsg(tc,cfg)
    if len(tc.Results)==0 { b.WriteString(call+"\n"); return }
    if len(nonErr)==0 && hasErr { if msgArgs!="" { b.WriteString("tt.assertion(t, "+call+", "+msgArgs+")\n") } else { b.WriteString("tt.assertion(t, "+call+")\n") }; return }
    if len(nonErr)==1 && !hasErr { r:=nonErr[0]; if msgArgs!="" { b.WriteString("assert.Equalf(t, tt."+r.WantName+", "+call+", "+msgArgs+")\n") } else { b.WriteString("assert.Equal(t, tt."+r.WantName+", "+call+")\n") }; return }
    vars:=[]string{}; for _,r:=range nonErr { vars=append(vars,r.GotName) }; if hasErr { vars=append(vars,"err") }
    b.WriteString(strings.Join(vars, ", ")+" := "+call+"\n")
    if hasErr { if msgArgs!="" { b.WriteString("tt.assertion(t, err, "+msgArgs+")\n") } else { b.WriteString("tt.assertion(t, err)\n") } }
    for _,r:= range nonErr { if msgArgs!="" { b.WriteString("assert.Equalf(t, tt."+r.WantName+", "+r.GotName+", "+msgArgs+")\n") } else { b.WriteString("assert.Equal(t, tt."+r.WantName+", "+r.GotName+")\n") } }
}

func callExpr(tc testCase, recv string) string {
    args:=[]string{}; for _,p:= range tc.Params { a:="tt.args."+p.Name; if p.Variadic { a += "..." }; args=append(args,a) }
    name:=tc.FuncName
    if tc.IsMethod { name = recv+"."+tc.FuncName } else if len(tc.TypeArgs)>0 { name += "["+strings.Join(tc.TypeArgs, ", ")+"]" }
    return name+"("+strings.Join(args, ", ")+")"
}
func nonErrorResults(rs []result) []result { var out []result; for _,r:=range rs { if !r.IsError { out=append(out,r) } }; return out }
func hasError(rs []result) bool { for _,r:=range rs { if r.IsError { return true } }; return false }

func comparisonExpr(r result, got, want string, cfg *config) string {
    if needsDeep(r.OriginalType, r.Type, nil) { if cfg.useCmp { return "!cmp.Equal("+want+", "+got+")" }; return "!reflect.DeepEqual("+got+", "+want+")" }
    return got+" != "+want
}

func errorfLine(tc testCase, cfg *config, kind, got, want string, fatal bool) string {
    method := "Errorf"; if fatal { method = "Fatalf" }
    prefix := ""; argsPrefix := ""
    if cfg.noSubtests { prefix = "%q. "; if cfg.named { argsPrefix="name, " } else { argsPrefix="tt.name, " } }
    fname := tc.DisplayName
    inputFmt, inputArgs := inputFormat(tc)
    if !cfg.printInputs { inputFmt = "()"; inputArgs = nil }
    formatStr := ""
    args := []string{}
    switch kind {
    case "error": formatStr = prefix+fname+inputFmt+" error = %v, wantErr %v"; args=[]string{got,want}
    case "single": formatStr = prefix+fname+inputFmt+" = %v, want %v"; args=[]string{got,want}
    case "multi": formatStr = prefix+fname+inputFmt+" "+got+" = %v, want %v"; args=[]string{got,want}
    }
    allArgs := append(inputArgs, args...)
    return fmt.Sprintf("t.%s(%q, %s%s)\n", method, formatStr, argsPrefix, strings.Join(allArgs, ", "))
}

func inputFormat(tc testCase) (string, []string) { if len(tc.Params)==0 { return "()", nil }; fs:=[]string{}; as:=[]string{}; for _,p:= range tc.Params { fs=append(fs,"%v"); as=append(as,"tt.args."+p.Name) }; return "("+strings.Join(fs, ", ")+")", as }
func testifyMsg(tc testCase, cfg *config) string { if !(cfg.noSubtests && cfg.printInputs) { return "" }; inFmt,inArgs:=inputFormat(tc); format := "%q. "+tc.DisplayName+inFmt; args:=[]string{"tt.name"}; args=append(args,inArgs...); return "fmt.Sprintf("+fmt.Sprintf("%q",format)+", "+strings.Join(args, ", ")+")" }

func needsDeep(orig, typ string, tparams map[string]bool) bool {
    if orig == "" { orig = typ }
    if tparams != nil { if tparams[strings.TrimSpace(orig)] { return true } }
    s:=strings.TrimSpace(orig)
    if strings.HasPrefix(s,"[]") || strings.HasPrefix(s,"map[") || strings.HasPrefix(s,"func(") || strings.HasPrefix(s,"chan ") || strings.HasPrefix(s,"<-chan") || strings.HasPrefix(s,"chan<-") || strings.HasPrefix(s,"[") || s=="any" || s=="interface{}" { return true }
    if strings.Contains(s,"[]") || strings.Contains(s,"map[") || strings.Contains(s,"interface{") { return true }
    if strings.Contains(s,".") { return true }
    if strings.HasPrefix(s,"*") { inner:=strings.TrimPrefix(s,"*"); if strings.HasPrefix(inner,"[]") || strings.HasPrefix(inner,"map[") { return true } }
    if isTypeParamName(s) { return true }
    return false
}
func isTypeParamName(s string) bool { return len(s)==1 && s[0]>='A' && s[0]<='Z' }

func structFields(st *ast.StructType) []structField {
    var out []structField
    for _, f := range st.Fields.List {
        typ:=exprString(f.Type)
        if len(f.Names)==0 { out=append(out, structField{Name:embeddedName(f.Type), Type:typ}); continue }
        for _,n:= range f.Names { out=append(out, structField{Name:n.Name, Type:typ}) }
    }
    return out
}
func embeddedName(e ast.Expr) string { switch x:=e.(type){ case *ast.Ident: return x.Name; case *ast.SelectorExpr: return x.Sel.Name; case *ast.StarExpr: return embeddedName(x.X) }; return exprString(e) }

func exprString(e ast.Expr) string { var b bytes.Buffer; _=printer.Fprint(&b, token.NewFileSet(), e); return b.String() }
func replaceTypeParams(s string, tm map[string]string) string { for k,v:= range tm { re:=regexp.MustCompile(`\b`+regexp.QuoteMeta(k)+`\b`); s=re.ReplaceAllString(s,v) }; return s }
func exportish(s string) string { if s=="" { return s }; r:=[]rune(s); if unicode.IsLower(r[0]) { return "_"+s }; return s }
func upperFirst(s string) string { if s=="" { return s }; r:=[]rune(s); r[0]=unicode.ToUpper(r[0]); return string(r) }

func writeTestFile(path, generated string, tests []testCase, imports []string) error {
    if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) { return os.WriteFile(path, []byte(generated), 0644) }
    old, err := os.ReadFile(path); if err != nil { return err }
    funcs := extractGeneratedFuncs(generated)
    content := strings.TrimRight(string(old), "\n") + "\n\n" + strings.Join(funcs, "\n\n") + "\n"
    content = ensureImports(content, imports)
    if out, err := format.Source([]byte(content)); err == nil { content=string(out) }
    return os.WriteFile(path, []byte(content), 0644)
}
func extractGeneratedFuncs(src string) []string { idx:=strings.Index(src,"\nfunc "); if idx<0 { return nil }; rest:=src[idx+1:]; parts:=regexp.MustCompile(`\nfunc Test`).Split(rest,-1); var out []string; for i,p:=range parts { if p=="" { continue }; if i==0 && strings.HasPrefix(p,"func ") { out=append(out,p) } else { out=append(out,"func Test"+p) } }; return out }
func ensureImports(content string, imports []string) string {
    for _, sp := range imports { if strings.Contains(content, sp) { continue }; content=addImport(content, sp) }
    return content
}
func addImport(content, sp string) string {
    lines:=strings.Split(content,"\n")
    for i,l:= range lines { if strings.HasPrefix(strings.TrimSpace(l),"import (") { lines=append(lines[:i+1], append([]string{"\t"+sp}, lines[i+1:]...)...); return strings.Join(lines,"\n") } }
    for i,l:= range lines { tr:=strings.TrimSpace(l); if strings.HasPrefix(tr,"import ") { old:=strings.TrimSpace(strings.TrimPrefix(tr,"import ")); lines[i]="import ("; lines=append(lines[:i+1], append([]string{"\t"+old,"\t"+sp,")"}, lines[i+1:]...)...); return strings.Join(lines,"\n") } }
    for i,l:= range lines { if strings.HasPrefix(l,"package ") { lines=append(lines[:i+1], append([]string{"","import "+sp}, lines[i+1:]...)...); return strings.Join(lines,"\n") } }
    return content
}
EOF"}

