cat >/tmp/gotimp/imports.go <<'EOF'
package p

import (
    "io"
    "net/http"
    tm "time"
    . "bytes"
)

func Timey(x tm.Time) tm.Duration { return 0 }
func HTTP(c *http.Client) io.Reader { return nil }
func Dotted(b Buffer) Buffer { return b }
EOF
cd /tmp/gotimp
/workspace/executable -all imports.go | sed -n '1,80p'

python3 - <<'PY'
from pathlib import Path
p=Path('cmd/gotests-reimpl/main.go')
s=p.read_text()
s=s.replace('''	tc.Results = resultsFromFields(fn.Type.Results, typeMap(fn.Type.TypeParams, pi))''', '''	tc.Results = resultsFromFields(fn.Type.Results, typeMap(fn.Type.TypeParams, pi))
	markNamedDeep(tc.Results, pi)''')
insert='''
func markNamedDeep(rs []result, pi *pkgInfo) {
	for i := range rs {
		if rs[i].IsError {
			continue
		}
		s := strings.TrimSpace(rs[i].OriginalType)
		if !regexp.MustCompile(`^[A-Za-z_]\w*$`).MatchString(s) || isBuiltinComparable(s) || isTypeParamName(s) {
			continue
		}
		if ti, ok := pi.Types[s]; ok {
			if ti.IsStruct {
				rs[i].OriginalType = "interface{}"
			}
		} else {
			rs[i].OriginalType = "interface{}"
		}
	}
}

func isBuiltinComparable(s string) bool {
	switch s {
	case "bool", "string", "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "byte", "rune", "float32", "float64", "complex64", "complex128":
		return true
	}
	return false
}
'''
s=s.replace('
func receiverInfo(e ast.Expr, pi *pkgInfo)', insert+'
func receiverInfo(e ast.Expr, pi *pkgInfo)')
p.write_text(s)
PY
gofmt -w cmd/gotests-reimpl/main.go
./compile.sh
cd /tmp/gotimp && /workspace/executable -only Dotted imports.go
